window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ae9ce7ab8ff64b3b"]={"versions": [{"id": "FIG-ae9ce7ab8ff64b3b", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR-Metamodell / Definitionsebene).\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li>Definiert die Top-Level-Metamodell-Struktur für die <strong>ECU-Konfigurations-Parameterdefinition</strong> (BSW-Modul-Deskriptoren).\n</li><li>Bildet die formale Schablone (Schema / Template), anhand derer konkrete BSW-Module (z. B. Can, Com, Os, Dem) und deren Konfigurationsparameter definiert werden, bevor diese in der ECU-Konfigurations-Wertemenge (<code>EcucValueCollection</code> bzw. Modulkonfigurationen) instanziiert werden.\n</li><li>Verankert die Konfigurationsdefinitionen in der globalen AUTOSAR-ARXML-Hierarchie als vollwertige Paket-Elemente (<code>ARElement</code>).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>ARObject</code>:</strong>\n<ul class=\"fig-list\"><li>Wurzelklasse des gesamten AUTOSAR-Metamodells.\n</li></ul>\n</li><li><strong><code>Identifiable</code></strong> (Stereotyp <code>«atpIdentifiable»</code>):\n<ul class=\"fig-list\"><li>Spezialisierung von <code>ARObject</code>.\n</li><li>Basis für alle adressierbaren Metamodell-Elemente im ARXML-Baum.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>shortName: Identifier</code> (eindeutiger Name innerhalb des Namensraums/Pfads).\n</li><li><code>category: String [0..1]</code> (semantische Subklassifikation).\n</li><li><code>uuid: String</code> (global eindeutige Identifikations-GUID).\n</li></ul>\n</li></ul>\n</li><li><strong><code>ARElement</code></strong> (Stereotyp <code>«atpIdentifiable»</code>, Eigenschaft <code>NonSplitableElement</code>):\n<ul class=\"fig-list\"><li>Spezialisierung von <code>Identifiable</code>.\n</li><li>Repräsentiert ein eigenständiges Top-Level-Element eines <code>AR-PACKAGE</code>.\n</li><li><code>NonSplitableElement</code>: Darf im Gegensatz zu splitbaren Elementen nicht über mehrere physische ARXML-Dateien aufgeteilt fragmentiert werden; die Definition muss atomar deklariert sein.\n</li></ul>\n</li><li><strong><code>EcuParameterDefinition</code>:</strong>\n<ul class=\"fig-list\"><li>Spezialisierung von <code>ARElement</code>.\n</li><li>Wurzelelement/Container der Parameterspezifikation für eine Steuergerätekonfiguration.\n</li></ul>\n</li><li><strong><code>ModuleDef</code></strong> (mit Mixin/Aspekt <code>ParamConfMultiplicity</code>):\n<ul class=\"fig-list\"><li>Spezialisierung von <code>ARElement</code>. Repräsentiert die Konfigurationsdefinition eines konkreten BSW-Moduls (z. B. <code>Can</code>, <code>Fee</code>).\n</li><li><strong>Attribut:</strong> <code>implementationConfigVariant: String [0..1]</code> (definiert die zulässigen/unterstützten Konfigurationsvarianten wie <em>PreCompile</em>, <em>LinkTime</em>, <em>PostBuild</em>).\n</li></ul>\n</li><li><strong><code>ContainerDef</code></strong> (mit Mixin/Aspekt <code>ParamConfMultiplicity</code>):\n<ul class=\"fig-list\"><li>Spezialisierung von <code>Identifiable</code> (ist <strong>kein</strong> <code>ARElement</code>, kann folglich nicht direkt in <code>AR-PACKAGE</code> liegen, sondern nur innerhalb eines Moduls bzw. Eltern-Containers).\n</li><li>Struktur- und Gruppierungselement für Parameter und Unter-Container.\n</li><li><strong>Attribut:</strong> <code>postBuildChangeable: Boolean</code> (normatives Flag, ob die Parameterwerte dieses Containers zur Laufzeit bzw. nach dem Kompilieren/Flushen als Post-Build-Loadable/Selectable austauschbar sein dürfen).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>EcuParameterDefinition</code> → <code>ModuleDef</code> (<code>+module</code>, Kardinalität <code>1..*</code>):</strong>\n<ul class=\"fig-list\"><li>Eine <code>EcuParameterDefinition</code> bündelt mindestens eine oder beliebig viele BSW-Moduldefinitionen.\n</li></ul>\n</li><li><strong><code>ModuleDef</code> ▶ <code>ContainerDef</code> (<code>+container</code>, Kardinalität <code>1..*</code>):</strong>\n<ul class=\"fig-list\"><li>Strenge Komposition: Ein BSW-Modul besteht aus mindestens einem Root-<code>ContainerDef</code>. Die Lebensdauer der Container ist fest an das übergeordnete <code>ModuleDef</code> gebunden.\n</li></ul>\n</li><li><strong><code>ModuleDef</code> → <code>ModuleDef</code> (<code>+refinedModuleDef</code>, Kardinalität <code>0..1</code>):</strong>\n<ul class=\"fig-list\"><li>Reflexive Assoziation zur <strong>Modul-Refinierung</strong> (<em>Module Refinement</em>): Ermöglicht es Halbleiter-/Stack-Vendors, eine standardisierte BSW-Moduldefinition (<code>ModuleDef</code>) durch herstellerspezifische Parameter und Container zu erweitern bzw. einzuschränken, ohne den AUTOSAR-Standarddeskriptor zu verändern.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell):</strong>\n<ul class=\"fig-list\"><li>Das Diagramm enthält keine Laufzeitinteraktionen, Zustände, Sequenzen oder OS-/Task-Trigger.\n</li><li><strong>Verarbeitungskontext im AUTOSAR-Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li>Bereitstellung der <code>ModuleDef</code>-Standardbeschreibungen durch den BSW-Lieferanten (BSW-Paket).\n</li><li>Optionales Ausführen der Refinement-Assoziation (<code>refinedModuleDef</code>) durch Vendor-Tools.\n</li><li>Einlesen der <code>EcuParameterDefinition</code> in den ECU-Konfigurator (z. B. DaVinci Configurator, EB tresos).\n</li><li>Validierung der Modul-Multiplizitäten (<code>ParamConfMultiplicity</code>) und Bindungsvarianten (<code>implementationConfigVariant</code>) gegen die konkreten Eingabewerte (<code>EcucModuleConfigurationValues</code>).\n</li></ol>\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Trennung von Metadaten und Werten:</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen strikt zwischen der Definitionsklasse (<code>ModuleDef</code>, <code>ContainerDef</code>) und der Instanziierungsebene (<code>EcucModuleConfigurationValues</code>, <code>EcucContainerValue</code>) unterscheiden. Änderungen hier betreffen Codegeneratoren und XML-Validatoren, nicht den C-Treiber direkt.\n</li></ul>\n</li><li><strong>Vendor Module Refinement (<code>refinedModuleDef</code>):</strong>\n<ul class=\"fig-list\"><li>Vendor-spezifische Erweiterungen (z. B. HW-spezifische Clock-Divider in <code>Mcu</code> oder erweiterte Filter in <code>Can</code>) dürfen die standardisierte <code>ModuleDef</code> nicht brechen. Das <code>refinedModuleDef</code> garantiert Rückwärtskompatibilität zum AUTOSAR-Standard bei gleichzeitiger Validierung herstellerspezifischer Konfigurationen.\n</li></ul>\n</li><li><strong>Einfluss auf Speicherklassen &amp; Codegenerierung (<code>postBuildChangeable</code> &amp; <code>implementationConfigVariant</code>):</strong>\n<ul class=\"fig-list\"><li><code>postBuildChangeable == true</code>: Container-Daten müssen im C-Code zwingend in relokierbaren Strukturen (RAM-Zeiger oder Flash-Blocks mit konstanter Basisadresse) abgelegt werden, typischerweise als Typ-Definitionen für Deskriptor-Arrays.\n</li><li><code>postBuildChangeable == false</code> (bzw. <em>PreCompile</em>): Parameter aus diesem Container fließen als Präprozessor-Makros (<code>#define</code>) oder <code>const</code>-Strukturen direkt in den ROM/Flash-Code ein.\n</li></ul>\n</li><li><strong>ARXML-Serialisierung (<code>NonSplitableElement</code>):</strong>\n<ul class=\"fig-list\"><li>Bei der Tool-Entwicklung und Versionskontrolle muss beachtet werden, dass <code>ModuleDef</code> als <code>NonSplitableElement</code> stets in einem konsistenten, nicht fragmentierten XML-Knoten persistiert wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-a6ede4f7b3ece0cd", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR-Metamodell / Definitionsebene).\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li>Definiert die Top-Level-Metamodell-Struktur für die <strong>ECU-Konfigurations-Parameterdefinition</strong> (BSW-Modul-Deskriptoren).\n</li><li>Bildet die formale Schablone (Schema / Template), anhand derer konkrete BSW-Module (z. B. Can, Com, Os, Dem) und deren Konfigurationsparameter definiert werden, bevor diese in der ECU-Konfigurations-Wertemenge (<code>EcucValueCollection</code> bzw. Modulkonfigurationen) instanziiert werden.\n</li><li>Verankert die Konfigurationsdefinitionen in der globalen AUTOSAR-ARXML-Hierarchie als vollwertige Paket-Elemente (<code>ARElement</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>ARElement</code></strong> (Eigenschaft <code>PackageableElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert ein eigenständiges Top-Level-Element eines Pakets (<code>AR-PACKAGE</code>).\n</li><li>Trägt die Kennzeichnung <code>PackageableElement</code> als verpackbares Metamodellelement.\n</li></ul>\n</li><li><strong><code>EcuParameterDefinition</code>:</strong>\n<ul class=\"fig-list\"><li>Spezialisierung von <code>ARElement</code>.\n</li><li>Wurzelelement der Parameterspezifikation für eine Steuergerätekonfiguration.\n</li></ul>\n</li><li><strong><code>ModuleDef</code></strong> (mit Mixin/Aspekt <code>ParamConfMultiplicity</code>):\n<ul class=\"fig-list\"><li>Spezialisierung von <code>ARElement</code>. Repräsentiert die Konfigurationsdefinition eines BSW-Moduls.\n</li><li><strong>Attribut:</strong> <code>supportedConfigVariant: ConfigurationVariant [1..*]</code> (definiert als Aufzählungstyp typisiert mit Kardinalität <code>1..*</code> die vom Modul unterstützten Konfigurationsvarianten wie <em>PreCompile</em>, <em>LinkTime</em> oder <em>PostBuild</em>).\n</li></ul>\n</li><li><strong><code>ContainerDef</code></strong> (mit Mixins/Aspekten <code>Identifiable</code>, <code>ParamConfMultiplicity</code>):\n<ul class=\"fig-list\"><li>Struktur- und Gruppierungselement für Parameter und Unter-Container, das die Eigenschaften von <code>Identifiable</code> und <code>ParamConfMultiplicity</code> inkorporiert.\n</li><li><strong>Attribut:</strong> <code>postBuildChangeable: Boolean</code> (normatives Flag, ob die Parameterwerte dieses Containers nach dem Kompilieren/Bauen austauschbar sein dürfen).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>EcuParameterDefinition</code> → <code>ModuleDef</code> (<code>+module</code>, Kardinalität <code>1..*</code>):</strong>\n<ul class=\"fig-list\"><li>Eine <code>EcuParameterDefinition</code> bündelt mindestens eine oder beliebig viele BSW-Moduldefinitionen.\n</li></ul>\n</li><li><strong><code>ModuleDef</code> ▶ <code>ContainerDef</code> (<code>+container</code>, Kardinalität <code>1..*</code>):</strong>\n<ul class=\"fig-list\"><li>Strenge Komposition: Ein BSW-Modul besteht aus mindestens einem Root-<code>ContainerDef</code>. Die Lebensdauer der Container ist fest an das übergeordnete <code>ModuleDef</code> gebunden.\n</li></ul>\n</li><li><strong><code>ModuleDef</code> → <code>ModuleDef</code> (<code>+refinedModuleDef</code>, Kardinalität <code>0..1</code>):</strong>\n<ul class=\"fig-list\"><li>Reflexive Assoziation zur Modul-Refinierung (<em>Module Refinement</em>): Ermöglicht die Spezialisierung bzw. Erweiterung einer bestehenden Moduldefinition.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell):</strong>\n<ul class=\"fig-list\"><li>Das Diagramm enthält keine Laufzeitinteraktionen, Zustände, Sequenzen oder OS-/Task-Trigger.\n</li><li><strong>Verarbeitungskontext im AUTOSAR-Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li>Bereitstellung der <code>ModuleDef</code>-Standardbeschreibungen durch den BSW-Lieferanten (BSW-Paket).\n</li><li>Optionales Ausführen der Refinement-Assoziation (<code>refinedModuleDef</code>) durch Vendor-Tools.\n</li><li>Einlesen der <code>EcuParameterDefinition</code> in den ECU-Konfigurator (z. B. DaVinci Configurator, EB tresos).\n</li><li>Validierung der Modul-Multiplizitäten (<code>ParamConfMultiplicity</code>) und Bindungsvarianten (<code>implementationConfigVariant</code>) gegen die konkreten Eingabewerte (<code>EcucModuleConfigurationValues</code>).\n</li></ol>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Verbindlichkeit der Struktur:</strong> Jede AUTOSAR-konforme BSW-Moduldefinition muss als <code>ModuleDef</code> angelegt sein und zwingend mindestens einen Wurzelcontainer (<code>+container [1..*]</code>) deklarieren.\n</li><li><strong>Paketierung:</strong> <code>EcuParameterDefinition</code> und <code>ModuleDef</code> sind als <code>ARElement</code> spezialisiert und tragen den Status <code>PackageableElement</code>, wodurch sie direkt in ARXML-Paketen verwaltet werden.\n</li><li><strong>Post-Build-Restriktion:</strong> Das Attribut <code>postBuildChangeable</code> an <code>ContainerDef</code> schreibt bindend vor, ob Werte der in diesem Container enthaltenen Parameter zur Post-Build-Zeit geändert werden dürfen.\n</li><li><strong>Konfigurationsvarianten:</strong> Durch das Attribut <code>supportedConfigVariant: ConfigurationVariant [1..*]</code> muss für jede Moduldefinition mindestens eine explizit typisierte Konfigurationsvariante verbindlich festgelegt sein.\n</li></ul>"}, {"id": "FIG-a938cae002bcfc93", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR-Metamodell / Definitionsebene).\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li>Definiert die Top-Level-Metamodell-Struktur für die <strong>ECU-Konfigurations-Parameterdefinition</strong> (BSW-Modul-Deskriptoren).\n</li><li>Bildet die formale Schablone (Schema / Template), anhand derer konkrete BSW-Module (z. B. Can, Com, Os, Dem) und deren Konfigurationsparameter definiert werden, bevor diese in der ECU-Konfigurations-Wertemenge (<code>EcucValueCollection</code> bzw. Modulkonfigurationen) instanziiert werden.\n</li><li>Verankert die Konfigurationsdefinitionen in der globalen AUTOSAR-ARXML-Hierarchie als vollwertige Paket-Elemente (<code>ARElement</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>ARElement</code></strong> (Eigenschaft <code>PackageableElement</code>):\n<ul class=\"fig-list\"><li>Repräsentiert ein eigenständiges Top-Level-Element eines Pakets (<code>AR-PACKAGE</code>).\n</li><li>Trägt die Kennzeichnung <code>PackageableElement</code> als verpackbares Metamodellelement.\n</li></ul>\n</li><li><strong><code>EcuParameterDefinition</code>:</strong>\n<ul class=\"fig-list\"><li>Spezialisierung von <code>ARElement</code>.\n</li><li>Wurzelelement der Parameterspezifikation für eine Steuergerätekonfiguration.\n</li></ul>\n</li><li><strong><code>ModuleDef</code></strong> (mit Mixin/Aspekt <code>ParamConfMultiplicity</code>):\n<ul class=\"fig-list\"><li>Spezialisierung von <code>ARElement</code>. Repräsentiert die Konfigurationsdefinition eines BSW-Moduls.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>apiServicePrefix :CIdentifier [0..1]</code> (definiert das C-Präfix für API-Funktionen und -Symbole des Moduls).\n</li><li><code>supportedConfigVariant :ConfigurationVariant [1..*]</code> (definiert als typisierte Aufzählung mit Kardinalität <code>1..*</code> die vom Modul unterstützten Konfigurationsvarianten).\n</li></ul>\n</li></ul>\n</li><li><strong><code>ContainerDef</code></strong> (mit Mixins/Aspekten <code>Identifiable</code>, <code>ParamConfMultiplicity</code>):\n<ul class=\"fig-list\"><li>Struktur- und Gruppierungselement für Parameter und Unter-Container, das die Eigenschaften von <code>Identifiable</code> und <code>ParamConfMultiplicity</code> inkorporiert.\n</li><li><strong>Attribut:</strong> <code>postBuildChangeable :Boolean</code> (normatives Flag, ob die Parameterwerte dieses Containers nach dem Kompilieren/Bauen austauschbar sein dürfen).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>EcuParameterDefinition</code> → <code>ModuleDef</code> (<code>+module</code>, Kardinalität <code>1..*</code>):</strong>\n<ul class=\"fig-list\"><li>Eine <code>EcuParameterDefinition</code> bündelt mindestens eine oder beliebig viele BSW-Moduldefinitionen.\n</li></ul>\n</li><li><strong><code>ModuleDef</code> ▶ <code>ContainerDef</code> (<code>+container</code>, Kardinalität <code>1..*</code>):</strong>\n<ul class=\"fig-list\"><li>Strenge Komposition: Ein BSW-Modul besteht aus mindestens einem Root-<code>ContainerDef</code>. Die Lebensdauer der Container ist fest an das übergeordnete <code>ModuleDef</code> gebunden.\n</li></ul>\n</li><li><strong><code>ModuleDef</code> → <code>ModuleDef</code> (<code>+refinedModuleDef</code>, Kardinalität <code>0..1</code>):</strong>\n<ul class=\"fig-list\"><li>Reflexive Assoziation zur Modul-Refinierung (<em>Module Refinement</em>): Ermöglicht die Spezialisierung bzw. Erweiterung einer bestehenden Moduldefinition.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell):</strong>\n<ul class=\"fig-list\"><li>Das Diagramm enthält keine Laufzeitinteraktionen, Zustände, Sequenzen oder OS-/Task-Trigger.\n</li><li><strong>Verarbeitungskontext im AUTOSAR-Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li>Bereitstellung der <code>ModuleDef</code>-Standardbeschreibungen durch den BSW-Lieferanten (BSW-Paket).\n</li><li>Optionales Ausführen der Refinement-Assoziation (<code>refinedModuleDef</code>) durch Vendor-Tools.\n</li><li>Einlesen der <code>EcuParameterDefinition</code> in den ECU-Konfigurator (z. B. DaVinci Configurator, EB tresos).\n</li><li>Validierung der Modul-Multiplizitäten (<code>ParamConfMultiplicity</code>) und Bindungsvarianten (<code>implementationConfigVariant</code>) gegen die konkreten Eingabewerte (<code>EcucModuleConfigurationValues</code>).\n</li></ol>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Verbindlichkeit der Struktur:</strong> Jede AUTOSAR-konforme BSW-Moduldefinition muss als <code>ModuleDef</code> angelegt sein und zwingend mindestens einen Wurzelcontainer (<code>+container [1..*]</code>) deklarieren.\n</li><li><strong>Paketierung:</strong> <code>EcuParameterDefinition</code> und <code>ModuleDef</code> sind als <code>ARElement</code> spezialisiert und tragen den Status <code>PackageableElement</code>, wodurch sie direkt in ARXML-Paketen verwaltet werden.\n</li><li><strong>Post-Build-Restriktion:</strong> Das Attribut <code>postBuildChangeable</code> an <code>ContainerDef</code> schreibt bindend vor, ob Werte der in diesem Container enthaltenen Parameter zur Post-Build-Zeit geändert werden dürfen.\n</li><li><strong>Konfigurationsvarianten:</strong> Durch das Attribut <code>supportedConfigVariant :ConfigurationVariant [1..*]</code> muss für jede Moduldefinition mindestens eine explizit typisierte Konfigurationsvariante verbindlich festgelegt sein.\n</li><li><strong>API-Präfixierung:</strong> Das optionale Attribut <code>apiServicePrefix :CIdentifier [0..1]</code> erlaubt die formale Festlegung eines C-konformen Namensraum-Präfixes für die Codegenerierung der Modul-Schnittstellen.\n</li></ul>"}], "trans": [{"from": "FIG-ae9ce7ab8ff64b3b", "to": "FIG-a6ede4f7b3ece0cd", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>Identifiable</code> und <code>ARObject</code>: Die separaten übergeordneten Basisklassen inklusive der Vererbungsbeziehung zu <code>ContainerDef</code> sowie der Attribute <code>category: String [0..1]</code>, <code>shortName: Identifier</code> und <code>uuid: String</code> sind nicht mehr dargestellt; stattdessen ist <code>Identifiable</code> als Aspekt/Mixin direkt an <code>ContainerDef</code> deklariert.\n</li><li><code>ARElement</code>: Die Eigenschaft <code>NonSplitableElement</code> und das Stereotyp <code>«atpIdentifiable»</code> wurden durch das Kursiv-Schlüsselwort/Mixin <code>PackageableElement</code> ersetzt.\n</li><li><code>ModuleDef</code>: Das Attribut <code>implementationConfigVariant: String [0..1]</code> wurde ersetzt durch <code>supportedConfigVariant: ConfigurationVariant [1..*]</code>.\n</li></ul>"}, {"from": "FIG-a6ede4f7b3ece0cd", "to": "FIG-a938cae002bcfc93", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>ModuleDef</code>: Um das optionale Attribut <code>apiServicePrefix :CIdentifier [0..1]</code> erweitert.\n</li></ul>"}]};
